1	package posemap
2	
3	// occurrence.go 承载“观测按所在帧时间归入当时那次出现”这一业务规则，
4	// 供打开地图文件时的归属校验（validateLoaded）与回环校正时的出现归组
5	// （Correct）共同使用，保证两处对时间边界的判断始终一致。
6	
7	// occurrenceWindow 是一次出现接纳观测的时间边界：
8	//
9	//   - 已知首次观测时间的出现只接纳不早于该时间的观测（端点包含）；
10	//   - 已失效的出现仍接纳失效时间上的观测（端点包含），之后的观测不再
11	//     属于它；
12	//   - 仍有效的出现没有失效时间上界；
13	//   - 首次观测时间未知（旧文件缺少逐帧来源）的出现没有下界，继续接纳
14	//     更早的历史观测，不把零当作补造的开始时间。
15	//
16	// 同一路标各次出现的时间区间互不重叠，因此任一时刻至多有一次出现接纳
17	// 观测；旧观测永远归入它所在帧当时的那次出现，不因后来出现了更新的
18	// 有效记录而改属。
19	type occurrenceWindow struct {
20		hasFirstSeen  bool
21		firstSeenTime int64
22		active        bool
23		invalidTime   int64
24	}
25	
26	// owns 判断时间 t 的观测是否属于这次出现。
27	func (w occurrenceWindow) owns(t int64) bool {
28		if w.hasFirstSeen && t < w.firstSeenTime {
29			return false
30		}
31		if !w.active && t > w.invalidTime {
32			return false
33		}
34		return true
35	}
36	
37	// occurrenceNumberAt 把时间 t 的一次观测归入当时的那次出现，返回 1 起
38	// 的出现编号；没有任何出现接纳时返回 0。
39	func occurrenceNumberAt(wins []occurrenceWindow, t int64) int {
40		for i, w := range wins {
41			if w.owns(t) {
42				return i + 1
43			}
44		}
45		return 0
46	}
47	
48	// window 返回该出现状态对应的时间边界。
49	func (o *occurrenceState) window() occurrenceWindow {
50		return occurrenceWindow{
51			hasFirstSeen:  o.hasFirstSeen,
52			firstSeenTime: o.firstSeenTime,
53			active:        o.active,
54			invalidTime:   o.invalidTime,
55		}
56	}
57	
58	// occurrenceAt 把时间 t 的观测归入该路标当时的那次出现，返回 1 起的
59	// 出现编号；不属于任何出现时返回 0。
60	func (lm *landmarkState) occurrenceAt(t int64) int {
61		for i, o := range lm.appearances {
62			if o.window().owns(t) {
63				return i + 1
64			}
65		}
66		return 0
67	}
68	
69	// occurrenceWindowsOf 从文件记录中提取一个路标各次出现的时间边界，供
70	// 打开文件时的观测归属校验使用。旧版平铺路标视为一次首次观测时间未知、
71	// 仍有效的第 1 次出现（无下界、无上界）。
72	func occurrenceWindowsOf(lm landmarkJSON) []occurrenceWindow {
73		if len(lm.Occurrences) == 0 {
74			return []occurrenceWindow{{active: true}}
75		}
76		wins := make([]occurrenceWindow, 0, len(lm.Occurrences))
77		for _, oj := range lm.Occurrences {
78			wins = append(wins, occurrenceWindow{
79				hasFirstSeen:  oj.HasFirstSeen,
80				firstSeenTime: oj.FirstSeenTime,
81				active:        oj.Active,
82				invalidTime:   oj.InvalidTime,
83			})
84		}
85		return wins
86	}
