107	// 逐帧观测指向不存在的路标：打开即报 ErrCorrupt，不返回地图对象。
108	// 拒绝时不改写原文件（另见 TestOpenRejectionLeavesFileUntouched）。
109	func TestOpenRejectsUnknownLandmarkObservation(t *testing.T) {
