1	package posemap
2	
3	import (
4		"math"
5		"sort"
6	)
7	
8	// Correct 提交一次已确认回环校正。
9	//
10	// req.ID 必须非空；req.Anchor 必须准确命中一个已导入帧的时间（不能是
11	// 初始位姿，也不借用历史查询得到的最近一帧）；目标位姿数值必须有限、
12	// 目标方差必须非负。命中后，锚点帧采用提交的位姿；从锚点到提交时末帧
13	// 的轨迹整体平移并旋转（保持这些帧在校正前彼此的相对位置与朝向，时间
14	// 不变，朝向归一到既有范围）；锚点之后每帧的方差等于目标方差加上锚点
15	// 之后至该帧的原运动方差累计值。更早的位姿不变。
16	//
17	// 受影响帧中的路标观测随新位姿改变地图位置；更早观测的地图位置不变。
18	// 同一路标仍按全部已接受观测、依原时间与同帧输入次序做增量平均并遵守
19	// 合并距离限制；观测次数不变。若校正后出现路标冲突，整次校正拒绝并说
20	// 明冲突帧时间与路标。输入或校正结果含非有限数值同样拒绝。
21	//
22	// 同一标识以相同内容重复提交返回首次结果且不再修改数据；同一标识不同
23	// 内容明确拒绝。任何拒绝或保存失败都不改变轨迹、路标与既有校正记录。
24	// 旧文件缺少逐帧观测来源时，覆盖其历史范围的校正返回 RejectNoBasis。
25	func (m *Map) Correct(req Correction) (CorrectionRecord, error) {
26		m.mu.Lock()
27		defer m.mu.Unlock()
28		if m.closed {
29			return CorrectionRecord{}, ErrClosed
30		}
31		st := m.state
32	
33		// 已保存校正：相同内容直接返回首次记录；不同内容明确拒绝。
34		// 不做任何校验或状态变更，即使其后又提交过其他校正。
35		if hash, ok := st.corrIndex[req.ID]; ok {
36			if hash == canonicalCorrectionHash(req.Anchor, req.Target) {
37				return cloneRecord(st.correctionRecordByID(req.ID)), nil
38			}
39			return CorrectionRecord{}, &RejectError{Kind: RejectCorrectionMismatch, Landmark: req.ID, HasLandmark: true}
40		}
41	
42		if req.ID == "" {
43			return CorrectionRecord{}, &RejectError{Kind: RejectEmptyID}
44		}
45		tgt := req.Target
46		if !isFinite(tgt.X) || !isFinite(tgt.Y) || !isFinite(tgt.Heading) || !isFinite(tgt.Variance) {
47			return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
48		}
49		if tgt.Variance < 0 {
50			return CorrectionRecord{}, &RejectError{Kind: RejectNegativeVariance, Time: req.Anchor, HasTime: true}
51		}
52	
53		// 锚点必须准确命中已导入帧：trajectory[0] 是初始位姿，不能校正。
54		anchorIdx := -1
55		for j := 1; j < len(st.trajectory); j++ {
56			if st.trajectory[j].Time == req.Anchor {
57				anchorIdx = j
58				break
59			}
60		}
61		if anchorIdx < 0 {
62			return CorrectionRecord{}, &RejectError{Kind: RejectAnchorNotFound, Time: req.Anchor, HasTime: true}
63		}
64		end := len(st.trajectory) - 1
65	
66		// 受影响范围内每一帧都必须有逐帧依据（旧文件没有，不能靠推测校正）。
67		for k := anchorIdx - 1; k < len(st.sources); k++ {
68			if st.sources[k] == nil {
69				return CorrectionRecord{}, &RejectError{Kind: RejectNoBasis, Time: req.Anchor, HasTime: true}
70			}
71		}
72	
73		oldAnchor := st.trajectory[anchorIdx]
74		newHeading := normalizeAngle(tgt.Heading)
75		// 相对位姿整体旋转 δ；平移锚点到目标位置。
76		dHeading := normalizeAngle(newHeading - oldAnchor.Heading)
77		cosD, sinD := math.Cos(dHeading), math.Sin(dHeading)
78	
79		// ---- 在副本上推演新位姿，真实状态此时保持不变 ----
80		next := append([]Pose(nil), st.trajectory...)
81		accumVar := tgt.Variance
82		for j := anchorIdx; j <= end; j++ {
83			old := st.trajectory[j]
84			if j > anchorIdx {
85				accumVar += st.sources[j-1].moveVariance
86			}
87			dx := old.X - oldAnchor.X
88			dy := old.Y - oldAnchor.Y
89			np := Pose{
90				Time:     old.Time,
91				X:        tgt.X + cosD*dx - sinD*dy,
92				Y:        tgt.Y + sinD*dx + cosD*dy,
93				Heading:  normalizeAngle(old.Heading + dHeading),
94				Variance: accumVar,
95			}
96			if !isFinite(np.X) || !isFinite(np.Y) || !isFinite(np.Heading) || !isFinite(np.Variance) {
97				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
98			}
99			next[j] = np
100		}
101	
102		// occKey 标识某一路标的某一次出现。回环校正跨越同一路标的多次出现
103		// 时，各次出现分别聚合、分别遵守合并距离限制。观测按所在帧时间归入
104		// 当时的那次出现，时间边界规则与打开文件时的归属校验共享（见
105		// occurrence.go）；已接受观测必然属于某次出现。
106		type occKey struct {
107			id  string
108			num int
109		}
110	
111		// 受影响的路标出现：在受影响帧中被观测到的全部（标识，出现编号）。
112		affected := make(map[occKey]struct{})
113		for j := anchorIdx; j <= end; j++ {
114			t := st.trajectory[j].Time
115			for _, ob := range st.sources[j-1].observations {
116				affected[occKey{id: ob.ID, num: st.landmarks[ob.ID].occurrenceAt(t)}] = struct{}{}
117			}
118		}
119		affectedKeys := make([]occKey, 0, len(affected))
120		for k := range affected {
121			affectedKeys = append(affectedKeys, k)
122		}
123		sort.Slice(affectedKeys, func(i, j int) bool {
124			if affectedKeys[i].id != affectedKeys[j].id {
125				return affectedKeys[i].id < affectedKeys[j].id
126			}
127			return affectedKeys[i].num < affectedKeys[j].num
128		})
129	
130		// 逐“出现”运行聚合：旧文件第 1 次出现的既有观测作为固定“旧贡献”
131		// 起点（位置不随校正改变），其余观测按帧时间与同帧输入次序、以当前/
132		// 校正后位姿重放，完整复刻导入时的增量平均与合并距离判定。同一路标的
133		// 不同出现互不参与彼此的合并。
134		type agg struct {
135			count int
136			x, y  float64
137		}
138		aggs := make(map[occKey]*agg, len(affectedKeys))
139		for _, k := range affectedKeys {
140			occ := st.landmarks[k.id].appearances[k.num-1]
141			a := &agg{}
142			if occ.legacyCount > 0 {
143				a.count = occ.legacyCount
144				a.x = occ.legacyMX
145				a.y = occ.legacyMY
146			}
147			aggs[k] = a
148		}
149		for j := 1; j <= end; j++ {
150			src := st.sources[j-1]
151			if src == nil {
152				continue // 旧文件帧：观测已计入对应出现的 legacy 起点
153			}
154			pose := next[j]
155			t := st.trajectory[j].Time
156			for _, ob := range src.observations {
157				k := occKey{id: ob.ID, num: st.landmarks[ob.ID].occurrenceAt(t)}
158				a, ok := aggs[k]
159				if !ok {
160					continue
161				}
162				mx, my := localToMap(pose.X, pose.Y, pose.Heading, ob.X, ob.Y)
163				if a.count > 0 && math.Hypot(mx-a.x, my-a.y) > st.config.MergeDistance {
164					return CorrectionRecord{}, &RejectError{
165						Kind:          RejectLandmarkConflict,
166						Time:          st.trajectory[j].Time,
167						HasTime:       true,
168						Landmark:      ob.ID,
169						HasLandmark:   true,
170						Occurrence:    k.num,
171						HasOccurrence: true,
172					}
173				}
174				a.x = mergeMean(a.x, mx, a.count)
175				a.y = mergeMean(a.y, my, a.count)
176				a.count++
177			}
178		}
179		for _, k := range affectedKeys {
180			a := aggs[k]
181			occ := st.landmarks[k.id].appearances[k.num-1]
